#!/usr/bin/env python3
"""Derive and validate the RNA-to-ATAC column permutation in Galaxy."""

import gzip
import itertools
import math
import re
import sys

N = 8
BIN = 10000


def open_text(path):
    with open(path, "rb") as f:
        gz = f.read(2) == b"\x1f\x8b"
    return gzip.open(path, "rt", encoding="utf-8") if gz else open(path, "rt", encoding="utf-8")


def gene_name(attr):
    m = re.search(r'gene_name\s+"([^"]+)"', attr)
    return m.group(1) if m else None


def read_rna(path):
    rows = []
    seen = set()
    with open_text(path) as fh:
        header = fh.readline().rstrip("\r\n").split("\t")
        for line_no, line in enumerate(fh, 2):
            if not line.strip():
                continue
            f = line.rstrip("\r\n").split("\t")
            if len(f) != N + 1:
                raise ValueError("RNA field count at line %d" % line_no)
            if f[0] in seen:
                continue
            seen.add(f[0])
            v = [float(x) for x in f[1:]]
            lv = [math.log1p(x) for x in v]
            m = sum(lv) / N
            rv = sum((x - m) ** 2 for x in lv) / N
            rows.append((f[0], v, rv))
    return header, rows, seen


def read_loci(path, wanted):
    loci = {}
    with open_text(path) as fh:
        for line in fh:
            if not line or line[0] == "#":
                continue
            f = line.rstrip("\r\n").split("\t")
            if len(f) != 9 or f[2] != "gene":
                continue
            name = gene_name(f[8])
            if name not in wanted or name in loci:
                continue
            start0 = int(f[3]) - 1
            end0 = int(f[4]) - 1
            tss0 = start0 if f[6] == "+" else end0
            loci[name] = (f[0], tss0)
    return loci


def key(chrom, b):
    return "%s_%d_%d" % (chrom, b * BIN, (b + 1) * BIN)


def bins_for_loci(loci, half_width):
    ans = {}
    targets = set()
    for name, (chrom, tss) in loci.items():
        if half_width == 0:
            bs = [tss // BIN]
        else:
            lo = max(0, tss - half_width) // BIN
            hi = (tss + half_width - 1) // BIN
            bs = range(lo, hi + 1)
        keys = [key(chrom, b) for b in bs]
        ans[name] = keys
        targets.update(keys)
    return ans, targets


def read_atac(path, targets):
    found = {}
    with open_text(path) as fh:
        header = fh.readline().rstrip("\r\n").split("\t")
        for line_no, line in enumerate(fh, 2):
            if not line.strip():
                continue
            f = line.rstrip("\r\n").split("\t")
            if len(f) != N + 1:
                raise ValueError("ATAC field count at line %d" % line_no)
            if f[0] in targets:
                found[f[0]] = [float(x) for x in f[1:]]
    return header, found


def zscore(v):
    m = sum(v) / N
    s = math.sqrt(sum((x - m) ** 2 for x in v) / N)
    return [(x - m) / s for x in v] if s else None


def score_matrix(pairs, log):
    w = [[0.0] * N for _ in range(N)]
    valid = 0
    for chrom, rv, av in pairs:
        if log:
            rv = [math.log1p(x) for x in rv]
            av = [math.log1p(x) for x in av]
        zr = zscore(rv)
        za = zscore(av)
        if zr is None or za is None:
            continue
        valid += 1
        for i in range(N):
            for a in range(N):
                w[i][a] += zr[i] * za[a]
    denom = valid * N
    return ([[x / denom for x in row] for row in w] if denom else [[0.0] * N for _ in range(N)]), valid


def top_assignments(m):
    out = []
    for p in itertools.permutations(range(N)):
        out.append((sum(m[i][p[i]] for i in range(N)) / N, p))
    out.sort(reverse=True)
    return out


def ptxt(p):
    return ";".join(str(x) for x in p)


def main():
    if len(sys.argv) != 6:
        raise SystemExit("usage: final.py RNA ATAC GTF ANSWER VALIDATION")
    rna_header, rna_rows, wanted = read_rna(sys.argv[1])
    loci = read_loci(sys.argv[3], wanted)
    bin_maps = {}
    targets = set()
    for label, width in (("tss_bin", 0), ("promoter_pm5kb", 5000)):
        bm, ts = bins_for_loci(loci, width)
        bin_maps[label] = bm
        targets.update(ts)
    atac_header, atac = read_atac(sys.argv[2], targets)
    method_pairs = {}
    for label, bm in bin_maps.items():
        pairs = []
        for name, rv, variance in rna_rows:
            keys = bm.get(name)
            if not keys:
                continue
            vals = [atac[k] for k in keys if k in atac]
            if not vals:
                continue
            av = [sum(v[i] for v in vals) for i in range(N)]
            pairs.append((loci[name][0], rv, av))
        method_pairs[label] = pairs

    matrices = {}
    with open(sys.argv[4], "w", encoding="utf-8") as val:
        val.write("# final Galaxy validation of RNA-to-ATAC permutation\n")
        val.write("rna_rows\t%d\ngenes_with_locus\t%d\natac_target_rows_found\t%d\n" % (len(rna_rows), len(loci), len(atac)))
        val.write("rna_header\t%s\natac_header\t%s\n" % ("\t".join(rna_header), "\t".join(atac_header)))
        val.write("analysis\tmatched_pairs\tpermutation_rna_to_atac\tbest_score\tsecond_score\tmargin\n")
        for method, pairs in method_pairs.items():
            for log in (False, True):
                label = method + ("_log1p" if log else "_raw")
                m, valid = score_matrix(pairs, log)
                matrices[label] = m
                tops = top_assignments(m)
                val.write("%s\t%d\t%s\t%.10g\t%.10g\t%.10g\n" % (label, valid, ptxt(tops[0][1]), tops[0][0], tops[1][0], tops[0][0] - tops[1][0]))

        # Equal-weight consensus of two coordinate windows and two monotone
        # transforms.  Each component is a mean within-gene standardized
        # cross-product, so its scale is directly comparable.
        consensus = [[0.0] * N for _ in range(N)]
        for m in matrices.values():
            for i in range(N):
                for a in range(N):
                    consensus[i][a] += m[i][a] / len(matrices)
        tops = top_assignments(consensus)
        p = tops[0][1]
        val.write("consensus_all\t%d\t%s\t%.10g\t%.10g\t%.10g\n" % (len(method_pairs["promoter_pm5kb"]), ptxt(p), tops[0][0], tops[1][0], tops[0][0] - tops[1][0]))

        # Check the same consensus criterion on disjoint genomic subsets and
        # on the most variable half of RNA genes, without using ATAC values to
        # select the validation subsets.
        groups = {
            "chr1_11": set("chr%d" % i for i in range(1, 12)),
            "chr12_22": set("chr%d" % i for i in range(12, 23)),
            "chrX": {"chrX"},
        }
        all_prom = method_pairs["promoter_pm5kb"]
        # The corresponding RNA row variances are reconstructed from the
        # unique RNA-name table, so selection is modality-independent.
        variance_by_name = {name: variance for name, rv, variance in rna_rows}
        # Use a deterministic expression-variance threshold for a separate
        # marker-enriched check.
        variances = sorted(variance_by_name.values())
        threshold = variances[len(variances) // 2] if variances else 0.0
        subset_specs = []
        for name, wanted_chroms in groups.items():
            subset_specs.append((name, [x for x in all_prom if x[0] in wanted_chroms]))
        # Build the variable subset by rejoining the names with their loci.
        variable_names = {name for name, rv, variance in rna_rows if variance >= threshold}
        variable_pairs = []
        for name, rv, variance in rna_rows:
            if name not in variable_names:
                continue
            keys = bin_maps["promoter_pm5kb"].get(name)
            if not keys:
                continue
            vals = [atac[k] for k in keys if k in atac]
            if vals:
                variable_pairs.append((loci[name][0], rv, [sum(v[i] for v in vals) for i in range(N)]))
        subset_specs[-1] = ("rna_variable_half", variable_pairs)
        for name, pairs in subset_specs:
            component = []
            for log in (False, True):
                m, valid = score_matrix(pairs, log)
                component.append(m)
            cm = [[(component[0][i][a] + component[1][i][a]) / 2.0 for a in range(N)] for i in range(N)]
            ts = top_assignments(cm)
            val.write("%s\t%d\t%s\t%.10g\t%.10g\t%.10g\n" % (name, len(pairs), ptxt(ts[0][1]), ts[0][0], ts[1][0], ts[0][0] - ts[1][0]))
    with open(sys.argv[5], "w", encoding="utf-8") as ans:
        ans.write(ptxt(p) + "\n")


